import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { closeLoginWindow, openBrowser } from "./browser.js";
const { execFile, spawn, platform } = vi.hoisted(() => ({
    execFile: vi.fn(),
    platform: vi.fn(() => "darwin"),
    spawn: vi.fn(),
}));
vi.mock("node:child_process", () => ({ execFile, spawn }));
vi.mock("node:os", () => ({
    default: { platform, homedir: () => "/test" },
}));
const url = "https://bitfab.ai/plugin/auth/codex?ticket=example";
beforeEach(() => {
    vi.clearAllMocks();
    vi.stubEnv("VITEST", "");
    vi.stubEnv("NODE_ENV", "development");
    platform.mockReturnValue("darwin");
    execFile.mockImplementation((_command, _args, _options, callback) => callback(null));
    spawn.mockReturnValue({ pid: 42, on: vi.fn(), unref: vi.fn() });
});
afterEach(() => vi.unstubAllEnvs());
describe("login browser launch", () => {
    it("opens the login URL in the OS-default browser", () => {
        expect(openBrowser(url)).toMatchObject({
            launched: true,
            method: "os-default",
        });
        expect(spawn).toHaveBeenCalledWith("open", [url], {
            detached: true,
            stdio: "ignore",
        });
    });
    it("reports failed launches for the manual sign-in fallback", () => {
        spawn.mockImplementation(() => {
            throw new Error("cannot spawn");
        });
        expect(openBrowser(url)).toMatchObject({
            launched: false,
            method: "none",
        });
    });
});
describe("login browser cleanup", () => {
    const marker = "0123456789abcdef0123456789abcdef";
    const signInUrl = `https://bitfab.ai/plugin/auth/codex?ticket=secret&loginWindow=${marker}`;
    it("only targets the originating login route and exact marker without a shell", async () => {
        await closeLoginWindow(signInUrl);
        expect(execFile).toHaveBeenCalledTimes(4);
        for (const [command, args, options] of execFile.mock.calls) {
            expect(command).toBe("osascript");
            expect(args.slice(2)).toEqual([
                "https://bitfab.ai/plugin/auth/codex?",
                marker,
            ]);
            expect(args[1]).toContain("is running then");
            expect(args[1]).toContain("tabUrl starts with loginPrefix");
            expect(args[1]).toContain('tabUrl contains ("?" & loginMarker) or tabUrl contains ("&" & loginMarker)');
            expect(args[1]).toContain("close t");
            expect(args[1]).not.toContain("secret");
            expect(args[1]).not.toContain("quit");
            expect(options).toEqual({ timeout: 4000 });
        }
        expect(execFile.mock.calls[2][1][1]).toContain('application "Brave Browser"');
        expect(spawn).not.toHaveBeenCalled();
    });
    it.each([
        "not a URL",
        "https://bitfab.ai/plugin/auth/codex",
        `https://bitfab.ai/datasets?loginWindow=${marker}`,
        `https://bitfab.ai/plugin/auth/codex/other?loginWindow=${marker}`,
        `file:///plugin/auth/codex?loginWindow=${marker}`,
        `https://user@bitfab.ai/plugin/auth/codex?loginWindow=${marker}`,
        `https://bitfab.ai/plugin/auth/codex?loginWindow=${marker}%22`,
    ])("ignores invalid or unrelated URL %s", async (invalidUrl) => {
        await closeLoginWindow(invalidUrl);
        expect(execFile).not.toHaveBeenCalled();
    });
    it("does nothing on other operating systems", async () => {
        platform.mockReturnValue("linux");
        await closeLoginWindow(signInUrl);
        expect(execFile).not.toHaveBeenCalled();
    });
    it("ignores denied automation permission and spawn failures", async () => {
        execFile.mockImplementationOnce(() => {
            throw new Error("spawn failed");
        });
        execFile.mockImplementation((_command, _args, _options, callback) => callback(new Error("denied")));
        await expect(closeLoginWindow(signInUrl)).resolves.toBeUndefined();
    });
});
